<?php
declare(strict_types=1);
/** Atelier Wood FulfilmentOS — v0.7.6 */
function fulfilment_root(): string { return data_root().'/private-domain/fulfilment'; }
function fulfilment_file(): string { return fulfilment_root().'/store.json'; }
function fulfilment_context(): string { return 'atelierwood:fulfilment:v1'; }
function fulfilment_ensure_dirs(): void { $d=fulfilment_root();if(!is_dir($d)&&!@mkdir($d,0750,true)&&!is_dir($d))throw new RuntimeException('Unable to create fulfilment store.');@chmod($d,0750); }
function fulfilment_empty(): array { return ['shipments'=>[],'installations'=>[],'events'=>[]]; }
function fulfilment_store(): array { fulfilment_ensure_dirs();try{$s=commerce_private_read(fulfilment_file(),fulfilment_context(),fulfilment_empty());}catch(Throwable){$s=fulfilment_empty();}return array_merge(fulfilment_empty(),$s); }
function fulfilment_mutate(callable $fn,string $reason): array { fulfilment_ensure_dirs();$out=[];commerce_private_mutate(fulfilment_file(),fulfilment_context(),function(array $s)use($fn,&$out){$s=array_merge(fulfilment_empty(),$s);$s=$fn($s);$out=$s;return$s;},$reason);return$out; }
function fulfilment_number(string $prefix): string { return $prefix.'-'.gmdate('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)); }
function fulfilment_shipments(): array { $r=fulfilment_store()['shipments'];usort($r,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));return$r; }
function fulfilment_shipment_by_guid(string $guid): ?array { foreach(fulfilment_store()['shipments'] as $x)if(($x['guid']??'')===$guid)return$x;return null; }
function fulfilment_shipment_for_order(string $orderGuid): ?array { foreach(fulfilment_store()['shipments'] as $x)if(($x['order_guid']??'')===$orderGuid)return$x;return null; }
function fulfilment_installation_for_order(string $orderGuid): ?array { foreach(fulfilment_store()['installations'] as $x)if(($x['order_guid']??'')===$orderGuid)return$x;return null; }
function fulfilment_order_ready(array $order): bool { return ($order['status']??'')==='READY_TO_DISPATCH'; }
function fulfilment_create_shipment(string $orderGuid): array { require_admin();if($existing=fulfilment_shipment_for_order($orderGuid))return$existing;$o=order_by_guid($orderGuid);if(!$o)throw new RuntimeException('Order not found.');if(!fulfilment_order_ready($o))throw new RuntimeException('Order must be READY_TO_DISPATCH before shipment creation.');$jobs=makeos_jobs_for_order($orderGuid);if($jobs&&count(array_filter($jobs,fn($j)=>($j['status']??'')==='READY_TO_DISPATCH'))!==count($jobs))throw new RuntimeException('All MakeOS jobs must be ready to dispatch.');$packages=[];foreach($o['items']??[] as $i=>$item)$packages[]=['guid'=>uuidv7(),'label'=>'Package '.($i+1).' · '.($item['name']??'Item'),'item_index'=>$i,'qty'=>(int)($item['qty']??1),'length_cm'=>0.0,'width_cm'=>0.0,'height_cm'=>0.0,'weight_kg'=>0.0,'fragile'=>true,'packed_verified'=>false];$ship=['guid'=>uuidv7(),'number'=>fulfilment_number('AWS'),'order_guid'=>$orderGuid,'order_number'=>$o['number'],'customer_guid'=>$o['customer_guid'],'address_snapshot'=>$o['address_snapshot'],'status'=>'READY','packages'=>$packages,'carrier'=>null,'service'=>null,'tracking_number'=>null,'tracking_url'=>null,'dispatch_note'=>'','created_at'=>gmdate('c'),'updated_at'=>gmdate('c'),'timeline'=>[['ts'=>gmdate('c'),'event'=>'SHIPMENT_CREATED','actor'=>'admin:'.(admin_identity()['guid']??'unknown')]]];fulfilment_mutate(function(array $s)use($ship){$s['shipments'][]=$ship;return$s;},'fulfilment.shipment.create');return$ship; }
function fulfilment_update_package(string $shipmentGuid,string $packageGuid,array $input): array { require_admin();$updated=null;fulfilment_mutate(function(array $s)use($shipmentGuid,$packageGuid,$input,&$updated){foreach($s['shipments'] as &$sh)if(($sh['guid']??'')===$shipmentGuid){if(!in_array(($sh['status']??''),['READY','BOOKED'],true))throw new RuntimeException('Packages cannot be changed after dispatch.');foreach($sh['packages'] as &$p)if(($p['guid']??'')===$packageGuid){foreach(['length_cm','width_cm','height_cm','weight_kg'] as $f)$p[$f]=max(0,(float)($input[$f]??0));$p['fragile']=!empty($input['fragile']);$p['packed_verified']=!empty($input['packed_verified']);$updated=$sh;break;}$sh['updated_at']=gmdate('c');break;}return$s;},'fulfilment.package.update');if(!$updated)throw new RuntimeException('Shipment/package not found.');return$updated; }
function fulfilment_book(string $shipmentGuid,array $input): array { require_admin();$carrier=trim((string)($input['carrier']??''));$tracking=trim((string)($input['tracking_number']??''));if($carrier===''||$tracking==='')throw new RuntimeException('Carrier and tracking number are required.');$updated=null;fulfilment_mutate(function(array $s)use($shipmentGuid,$input,$carrier,$tracking,&$updated){foreach($s['shipments'] as &$sh)if(($sh['guid']??'')===$shipmentGuid){if(($sh['status']??'')!=='READY')throw new RuntimeException('Only a ready shipment can be booked.');foreach($sh['packages'] as $p)if(empty($p['packed_verified']))throw new RuntimeException('Every package must be packing-verified.');$sh['carrier']=$carrier;$sh['service']=trim((string)($input['service']??''));$sh['tracking_number']=$tracking;$sh['tracking_url']=trim((string)($input['tracking_url']??''));$sh['status']='BOOKED';$sh['booked_at']=gmdate('c');$sh['updated_at']=gmdate('c');$sh['timeline'][]=['ts'=>gmdate('c'),'event'=>'CARRIER_BOOKED','actor'=>'admin:'.(admin_identity()['guid']??'unknown'),'note'=>$carrier.' · '.$tracking];$updated=$sh;break;}return$s;},'fulfilment.book');if(!$updated)throw new RuntimeException('Shipment not found.');return$updated; }
function fulfilment_dispatch(string $shipmentGuid,string $note=''): array { require_admin();$sh=fulfilment_shipment_by_guid($shipmentGuid);if(!$sh)throw new RuntimeException('Shipment not found.');$o=order_by_guid($sh['order_guid']);if(!$o||($o['status']??'')!=='READY_TO_DISPATCH')throw new RuntimeException('Order is not ready to dispatch.');$updated=null;fulfilment_mutate(function(array $s)use($shipmentGuid,$note,&$updated){foreach($s['shipments'] as &$x)if(($x['guid']??'')===$shipmentGuid){if(($x['status']??'')!=='BOOKED')throw new RuntimeException('Book a carrier before dispatch.');$x['status']='DISPATCHED';$x['dispatched_at']=gmdate('c');$x['dispatch_note']=trim($note);$x['updated_at']=gmdate('c');$x['timeline'][]=['ts'=>gmdate('c'),'event'=>'DISPATCHED','actor'=>'admin:'.(admin_identity()['guid']??'unknown'),'note'=>trim($note)];$updated=$x;break;}return$s;},'fulfilment.dispatch');order_transition($o['guid'],'SHIPPED','fulfilment','Carrier dispatch confirmed: '.$updated['carrier'].' '.$updated['tracking_number']);return$updated; }
function fulfilment_update_transit(string $shipmentGuid,string $status,string $note=''): array { require_admin();$status=strtoupper(trim($status));if(!in_array($status,['IN_TRANSIT','OUT_FOR_DELIVERY','DELIVERED','EXCEPTION'],true))throw new RuntimeException('Invalid transit status.');$updated=null;fulfilment_mutate(function(array $s)use($shipmentGuid,$status,$note,&$updated){foreach($s['shipments'] as &$x)if(($x['guid']??'')===$shipmentGuid){if(!in_array(($x['status']??''),['DISPATCHED','IN_TRANSIT','OUT_FOR_DELIVERY','EXCEPTION'],true))throw new RuntimeException('Shipment is not in transit.');$x['status']=$status;$x['updated_at']=gmdate('c');$x['timeline'][]=['ts'=>gmdate('c'),'event'=>$status,'actor'=>'admin:'.(admin_identity()['guid']??'unknown'),'note'=>trim($note)];if($status==='DELIVERED')$x['delivered_at']=gmdate('c');$updated=$x;break;}return$s;},'fulfilment.transit');if(!$updated)throw new RuntimeException('Shipment not found.');if($status==='DELIVERED'){$o=order_by_guid($updated['order_guid']);$needsInstall=(int)($o['pricing']['installation']??0)>0;$inst=fulfilment_installation_for_order($o['guid']);if(!$needsInstall||($inst&&($inst['status']??'')==='COMPLETED')){if(($o['status']??'')==='SHIPPED')$delivered=order_transition($o['guid'],'DELIVERED','fulfilment','Carrier delivery confirmed'.($needsInstall?' after installation.':'.'));if(function_exists('passport_issue_for_order'))passport_issue_for_order($delivered['guid']);}}return$updated; }
function fulfilment_schedule_installation(string $orderGuid,array $input): array { require_admin();$o=order_by_guid($orderGuid);if(!$o)throw new RuntimeException('Order not found.');if((int)($o['pricing']['installation']??0)<=0)throw new RuntimeException('This order does not include installation.');$date=trim((string)($input['scheduled_date']??''));$slot=trim((string)($input['time_slot']??''));if($date===''||$slot==='')throw new RuntimeException('Installation date and time slot are required.');$inst=fulfilment_installation_for_order($orderGuid);$guid=$inst['guid']??uuidv7();$row=['guid'=>$guid,'number'=>$inst['number']??fulfilment_number('AWI'),'order_guid'=>$orderGuid,'order_number'=>$o['number'],'customer_guid'=>$o['customer_guid'],'scheduled_date'=>$date,'time_slot'=>$slot,'team'=>trim((string)($input['team']??'')),'status'=>'SCHEDULED','notes'=>trim((string)($input['notes']??'')),'updated_at'=>gmdate('c'),'created_at'=>$inst['created_at']??gmdate('c')];fulfilment_mutate(function(array $s)use($row,$inst){if($inst){foreach($s['installations'] as &$x)if(($x['guid']??'')===$row['guid']){$x=$row;return$s;}}$s['installations'][]=$row;return$s;},'fulfilment.installation.schedule');return$row; }
function fulfilment_installation_action(string $guid,string $action,string $note=''): array { require_admin();$action=strtoupper(trim($action));$updated=null;fulfilment_mutate(function(array $s)use($guid,$action,$note,&$updated){foreach($s['installations'] as &$x)if(($x['guid']??'')===$guid){$from=$x['status']??'';$map=['CONFIRM'=>'CONFIRMED','COMPLETE'=>'COMPLETED','FAIL'=>'FAILED'];$to=$map[$action]??null;if(!$to)throw new RuntimeException('Invalid installation action.');if($from==='COMPLETED')throw new RuntimeException('Installation is already complete.');$x['status']=$to;$x['action_note']=trim($note);$x['updated_at']=gmdate('c');if($to==='COMPLETED')$x['completed_at']=gmdate('c');$updated=$x;break;}return$s;},'fulfilment.installation.action');if(!$updated)throw new RuntimeException('Installation not found.');if(($updated['status']??'')==='COMPLETED'){$sh=fulfilment_shipment_for_order($updated['order_guid']);$o=order_by_guid($updated['order_guid']);if($sh&&($sh['status']??'')==='DELIVERED'&&$o&&($o['status']??'')==='SHIPPED')$delivered=order_transition($o['guid'],'DELIVERED','installation','Installation completed after carrier delivery.');if(function_exists('passport_issue_for_order'))passport_issue_for_order($delivered['guid']);}return$updated; }
function fulfilment_customer_tracking(string $orderGuid,?string $customerGuid=null): ?array { $customerGuid=$customerGuid?:((string)(customer_identity()['guid']??''));$sh=fulfilment_shipment_for_order($orderGuid);if(!$sh||($sh['customer_guid']??'')!==$customerGuid)return null;$inst=fulfilment_installation_for_order($orderGuid);return ['number'=>$sh['number'],'status'=>$sh['status'],'carrier'=>$sh['carrier'],'tracking_number'=>$sh['tracking_number'],'tracking_url'=>$sh['tracking_url'],'dispatched_at'=>$sh['dispatched_at']??null,'delivered_at'=>$sh['delivered_at']??null,'installation'=>$inst?['number'=>$inst['number'],'status'=>$inst['status'],'scheduled_date'=>$inst['scheduled_date'],'time_slot'=>$inst['time_slot']]:null]; }
function fulfilment_release_checks(): array { $s=fulfilment_store();$shipmentNums=array_column($s['shipments'],'number');$instNums=array_column($s['installations'],'number');$links=true;$states=true;foreach($s['shipments'] as $sh){$o=order_by_guid((string)($sh['order_guid']??''));if(!$o)$links=false;if(($sh['status']??'')==='DISPATCHED'&&($o['status']??'')==='READY_TO_DISPATCH')$states=false;if(($sh['status']??'')==='DELIVERED'&&!in_array(($o['status']??''),['SHIPPED','DELIVERED'],true))$states=false;}$raw=is_file(fulfilment_file())?(string)file_get_contents(fulfilment_file()):'';$encrypted=$raw===''||!str_contains($raw,'shipments');return [
 ['name'=>'Fulfilment encryption','ok'=>$encrypted,'detail'=>'Shipment/installation records are encrypted at rest.'],
 ['name'=>'Shipment number uniqueness','ok'=>count($shipmentNums)===count(array_unique($shipmentNums)),'detail'=>'Shipment references are unique.'],
 ['name'=>'Installation number uniqueness','ok'=>count($instNums)===count(array_unique($instNums)),'detail'=>'Installation references are unique.'],
 ['name'=>'Fulfilment order linkage','ok'=>$links,'detail'=>'Every shipment remains linked to an order.'],
 ['name'=>'Fulfilment state synchronization','ok'=>$states,'detail'=>'Shipment state remains consistent with commerce order state.'],
 ]; }
fulfilment_ensure_dirs();
